const PAPER_FORMATS={a4:{label:'A4 portrait',w:210,h:297},a3:{label:'A3 portrait',w:297,h:420},a5:{label:'A5 flyer',w:148,h:210},letter:{label:'US Letter',w:215.9,h:279.4},square:{label:'Square',w:200,h:200},landscape:{label:'A4 landscape',w:297,h:210},story:{label:'Story 9:16',w:108,h:192},social:{label:'Social 4:5',w:200,h:250},custom:{label:'Custom size',w:210,h:297}};
function paperSize(s){const f=PAPER_FORMATS[s.paper]||PAPER_FORMATS.a4;return s.paper==='custom'?{label:'Custom size',w:Math.max(30,Math.min(1000,Number(s.customWidth)||210)),h:Math.max(30,Math.min(1000,Number(s.customHeight)||297))}:f;}
function posterDimensions(s){const f=paperSize(s);return{width:600,height:Math.round(600*f.h/f.w)};}
